css:
.top {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 16px;
  background-color: #18181b;
  font-family: system-ui, sans-serif;
}

.top a {
  color: #fafafa;
  text-decoration: none;
}

.logo {
  font-weight: 700;
}

.links {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

@media (min-width: 600px) {
  .top {
    flex-direction: row;
    justify-content: space-between;
    align-items: center;
  }

  .links {
    flex-direction: row;
    gap: 20px;
  }
}
